import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    permutation = list(map(int, data[1:]))

    min_val = float('inf')
    max_val = float('-inf')

    for i in range(n):
        if permutation[i] < min_val:
            min_val = permutation[i]
        if permutation[i] > max_val:
            max_val = permutation[i]

        if min_val < max_val:
            print("YES")
            return

    print("NO")

if __name__ == "__main__":
    main()
